fn solve(input: Vec<char>) -> Vec<char> {
    // The input has format:
    // "AtCoder <Name> Contest\n"
    // where:
    // - "AtCoder " prefix (7 chars + 1 space = 8 chars in total)
    // - <Name>: first uppercase letter, then zero or more lowercase letters, then space
    // - "Contest" exactly
    // - '\n' at end

    // Confirm prefix "AtCoder "
    let prefix = ['A','t','C','o','d','e','r',' '];
    for i in 0..prefix.len() {
        if input.get(i) != Some(&prefix[i]) {
            // According to problem statement assumptions, input is valid,
            // so no error handling needed. Just return empty if invalid.
            return vec![];
        }
    }

    // The first character of the name is at position 8 (0-based)
    let name_initial = match input.get(8) {
        Some(c) if c.is_ascii_uppercase() => *c,
        _ => return vec![],
    };

    // Validate the rest of the name: starting from index 9 until next space
    // At least one character in the name, so index 8 is uppercase,
    // subsequent chars must be lowercase letters until space
    let mut i = 9;
    let len = input.len();

    while i < len {
        match input.get(i) {
            Some(' ') => break, // end of name
            Some(c) if c.is_ascii_lowercase() => i += 1,
            _ => return vec![], // invalid character in name
        }
    }

    // After name, there is a space (at index i)
    // Check the substring after the space matches "Contest\n"
    // i is index of space, so contest should start at i+1
    let contest_str = ['C','o','n','t','e','s','t'];
    let contest_start = i + 1;
    let contest_end = contest_start + contest_str.len();

    if contest_end >= len {
        return vec![];
    }

    for (j, &ch) in contest_str.iter().enumerate() {
        if input.get(contest_start + j) != Some(&ch) {
            return vec![];
        }
    }

    // After "Contest" must be '\n' at the end (last char)
    if input[len - 1] != '\n' {
        return vec![];
    }

    // Also the total length should equal contest_end + 1 (because of '\n')
    if contest_end + 1 != len {
        return vec![];
    }

    build_result(name_initial)
}

fn build_result(ch: char) -> Vec<char> {
    vec!['A', ch, 'C', '\n']
}